1.reproduce_code:
// server.js – Node/Express server that serves HTML and delays the CSS
const express = require('express');
const app = express();
const PORT = 8000;

// Delayed CSS endpoint (5s delay)
app.get('/slow.css', (req, res) => {
  setTimeout(() => {
    res.set('Content-Type', 'text/css');
    // empty CSS (no styles)
    res.send('/* intentionally empty */');
  }, 5000);
});

// HTML page that uses rel=preload pattern
app.get('/preload-control.html', (req, res) => {
  res.set('Content-Type', 'text/html');
  res.send(`
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <title>Preload Control Test</n>
  <!-- Preload the stylesheet, then swap rel to stylesheet on load -->
  <link rel="preload" href="/slow.css" as="style"
        onload="this.rel='stylesheet'; this.onload=null;">
</head>
<body>
  <h1>Preload-Control Test</h1>
  <p>If Lighthouse flags slow.css in a critical chain, this reproduces the bug.</p>
</body>
</html>
  `);
});

app.listen(PORT, () => console.log(`Server listening on http://localhost:${PORT}`));

1.explanation:
1. Run the server with `node server.js`. It serves /preload-control.html and /slow.css (with 5 s delay).
2. In a separate terminal, invoke Lighthouse (CLI or programmatic) against http://localhost:8000/preload-control.html:
   • CLI: `lighthouse http://localhost:8000/preload-control.html --output html --view`
   • Programmatic (Node script):
```js
const lighthouse = require('lighthouse');
const chromeLauncher = require('chrome-launcher');
(async () => {
  const chrome = await chromeLauncher.launch({chromeFlags: ['--headless']});
  const opts = {port: chrome.port};
  const result = await lighthouse('http://localhost:8000/preload-control.html', opts);
  console.log('Diagnostics:', result.lhr.audits['critical-request-chains'].details);
  await chrome.kill();
})();
```
3. Observe the Performance > Diagnostics section: Lighthouse will list the delayed CSS (slow.css) under Critical Request Chains, showing ~5 s blocking—even though rel=preload should not block rendering.
